--- v1
+++ v2
@@ -6,11 +6,27 @@
 @prefix nltl: <https://w3id.org/nltl/vocab#> .

 # -----------------------------------------------------------------
-#  Ship shape – every ship must be linked to a steel‑grade requirement case
+# Ship shape – every ship must be linked to a steel‑grade requirement case
+# and must have a polar class value. Activation is confined to the declared
+# ship population.
 # -----------------------------------------------------------------
 _:ShipShape
     a sh:NodeShape ;
     sh:targetClass nltl:ship ;
+    # Activation guard – only nodes typed as nltl:ship are evaluated
+    sh:property [
+        sh:path rdf:type ;
+        sh:hasValue nltl:ship ;
+        sh:description "Activation confined to the declared ship population" ;
+    ] ;
+    # Ship must have a polar class value
+    sh:property [
+        sh:path nltl:polarClass ;
+        sh:class nltl:polarClassValue ;
+        sh:minCount 1 ;
+        sh:description "Polar class of the ship (I2.12.1)." ;
+    ] ;
+    # Ship must be linked to at least one steel‑grade requirement case
     sh:property [
         sh:path nltl:hasSteelGradeRequirementCase ;
         sh:class nltl:steelGradeRequirementCase ;
@@ -19,8 +35,8 @@
     ] .

